const rows = $input.all()
  .map(i => i.json)
  .filter(r => r.handling_type !== undefined && r.handling_type !== null);

if (rows.length === 0) {
  return [{ json: { message: "לא נמצאה הצהרה עם מספר זה במערכת" }, pairedItem: 0 }];
}

const formatDate = (d) => d === '00000000' ? '❌' : `${d.slice(6,8)}/${d.slice(4,6)}/${d.slice(0,4)}`;

const isFull = rows[0].handling_type === 'HH';

const blocks = rows.map(r => {
  if (isFull) {
    return `מכולה ${r.Container}\n` +
           `תאריך כניסה: ${formatDate(r.entry_date)}\n` +
           `התרת מכס: ${r.has_customs === 1 ? '✅' : '❌'}\n` +
           `תעודת ליווי: ${r.has_livoi === 1 ? '✅' : '❌'}\n` +
           `תאריך יציאה: ${formatDate(r.exit_date)}`;
  } else {
    return `עסקה ${r.deal_number}\n` +
           `כמות: ${r.qty}\n` +
           `משקל: ${r.weight} ק"ג\n` +
           `התרת מכס: ${r.has_customs === 1 ? '✅' : '❌'}\n` +
           `תעודת ליווי: ${r.has_livoi === 1 ? '✅' : '❌'}\n` +
           `תאריך יציאה: ${formatDate(r.exit_date)}`;
  }
});

const BATCH_SIZE = 30;
const batches = [];
for (let i = 0; i < blocks.length; i += BATCH_SIZE) {
  batches.push(blocks.slice(i, i + BATCH_SIZE));
}

const header = isFull ? '📦 מכולות תחת ההצהרה' : '💼 עסקאות תחת ההצהרה';

return batches.map(batch => ({
  json: { message: `${header}\n\n${batch.join('\n\n')}` },
  pairedItem: 0
}));

