const item = $input.first().json;

function fmtDate(iso) {
  const [yyyy, mm, dd] = iso.split('T')[0].split('-');
  return `${dd}/${mm}/${yyyy}`;
}

function fmtTime(iso) {
  const [hh, min] = iso.split('T')[1].split(':');
  return `${hh}:${min}`;
}

let message;
if (item.ex_date) {
  message = `המכולה יצאה משיקוף בתאריך: ${fmtDate(item.ex_date)} ובשעה: ${fmtTime(item.ex_date)}`;
} else if (item.in_date) {
  message = `המכולה נכנסה לשיקוף בתאריך: ${fmtDate(item.in_date)} ובשעה: ${fmtTime(item.in_date)}`;
} else if (item.scan_booked) {
  message = `שיקוף הוזמן לתאריך: ${fmtDate(item.scan_booked)} ובשעה: ${fmtTime(item.scan_booked)}`;
} else {
  message = 'למכולה לא מתוכננת שיקוף 🚫';
}

return [{ json: { ...item, message } }];

