const item = $input.first().json;

function todayStr() {
  const d = new Date();
  const yyyy = d.getFullYear();
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd}`;
}

function fmtDate(dbDate) {
  const [yyyy, mm, dd] = dbDate.split('T')[0].split('-');
  return `${dd}/${mm}/${yyyy}`;
}

let message;
if (!item.customs_registered) {
  message = '🚫 לא צפויה בדיקת מכס פיזי למכולה';
} else {
  const checkDate = item.customs_registered.split('T')[0];
  const today = todayStr();

  if (today < checkDate) {
    message = `בדיקת מכס פיזי צפויה למכולה בתאריך: ${fmtDate(item.customs_registered)}`;
  } else if (today === checkDate) {
    message = `המכולה נמצאת כעת בבדיקת מכס פיזי החל מתאריך: ${fmtDate(item.customs_registered)}`;
  } else {
    message = `המכולה יצאה מבדיקת מכס פיזי בתאריך: ${fmtDate(item.customs_registered)}`;
  }
}

return [{ json: { ...item, message } }];

