const items = $input.all();
if (items.length === 0) {
  return [{ json: { message: 'לא נמצאו מכולות נוספות בעסקה זו' } }];
}

function fmtDate(iso) {
  const [yyyy, mm, dd] = iso.split('T')[0].split('-');
  return `${dd}/${mm}/${yyyy}`;
}
function fmtTime(iso) {
  const [hh, min] = iso.split('T')[1].split(':');
  return `${hh}:${min}`;
}
function todayStr() {
  const d = new Date();
  const yyyy = d.getFullYear();
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd}`;
}

const lines = items.map(item => {
  const j = item.json;
  const entryDate = j.entry_date === '00000000' ? '❌' : j.entry_date.slice(6,8) + '/' + j.entry_date.slice(4,6) + '/' + j.entry_date.slice(0,4);
  const exitDate = j.exit_date === '00000000' ? '❌' : j.exit_date.slice(6,8) + '/' + j.exit_date.slice(4,6) + '/' + j.exit_date.slice(0,4);

const livoiDate = j.livoi_date ? `${fmtDate(j.livoi_date)} ${fmtTime(j.livoi_date)}` : '❌';
let block = `📦 מכולה מספר: ${j.container_number}\nתעודת ליווי: ${livoiDate}\nתאריך כניסה: ${entryDate}\nתאריך יציאה: ${exitDate}`;
  if (j.ex_date) {
    block += `\nהמכולה יצאה משיקוף בתאריך: ${fmtDate(j.ex_date)} ובשעה: ${fmtTime(j.ex_date)}`;
  } else if (j.in_date) {
    block += `\nהמכולה נכנסה לשיקוף בתאריך: ${fmtDate(j.in_date)} ובשעה: ${fmtTime(j.in_date)}`;
  } else if (j.scan_booked) {
    block += `\nשיקוף הוזמן לתאריך: ${fmtDate(j.scan_booked)} ובשעה: ${fmtTime(j.scan_booked)}`;
  }

  if (j.customs_registered) {
    const checkDate = j.customs_registered.split('T')[0];
    const today = todayStr();
    if (today < checkDate) {
      block += `\nבדיקת מכס פיזי צפויה למכולה בתאריך: ${fmtDate(j.customs_registered)}`;
    } else if (today === checkDate) {
      block += `\nהמכולה נמצאת כעת בבדיקת מכס פיזי החל מתאריך: ${fmtDate(j.customs_registered)}`;
    } else {
      block += `\nהמכולה יצאה מבדיקת מכס פיזי בתאריך: ${fmtDate(j.customs_registered)}`;
    }
  }

  return block;
});

const BATCH_SIZE = 30;
const batches = [];
for (let i = 0; i < lines.length; i += BATCH_SIZE) {
  batches.push(lines.slice(i, i + BATCH_SIZE));
}

return batches.map(batch => ({ json: { message: batch.join('\n\n') }, pairedItem: 0 }));

